def algorithm(func, dim, lb, ub, budget, rng):
    best_x = np.zeros(dim)
    best_y = float('inf')

    for i in range(budget):
        x = np.clip(rng.uniform(lb, ub, size=dim), a_min=lb, a_max=ub)

        y = func(x)
        if y < best_y:
            best_x = x
            best_y = y

    return best_x
